import { rxFromStream, txToStream } from "./rxtx-stream_node.js";
import { Transport } from "./transport_node.js";
/** Node.js stream-based transport. */
export class StreamTransport extends Transport {
    conn;
    constructor(conn, attrs = {}) {
        super(attrs);
        this.conn = conn;
        this.rx = rxFromStream(conn);
    }
    /** Report MTU as Infinity. */
    get mtu() { return Infinity; }
    rx;
    tx(iterable) {
        return txToStream(this.conn, iterable);
    }
}
